"""Generate a Gazebo world (.sdf.xacro) and matching Nav2 map (.pgm + .yaml) from a layout YAML.

Usage: python scripts/build_world.py simulation/worlds/qr_warehouse_small.layout.yaml
"""

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np
import yaml

ROOT = Path(__file__).resolve().parents[1]

HEADER = """<?xml version="1.0"?>
<!-- GENERATED by scripts/build_world.py from {src}. Do not edit by hand. -->
<sdf version="1.6" xmlns:xacro="http://www.ros.org/wiki/xacro">
  <xacro:arg name="headless" default="true"/>
  <world name="default">
    <plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics"/>
    <plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands"/>
    <!-- Always on (not only with GUI): publishes /world/default/pose/info, bridged as ground truth. -->
    <plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster"/>
    <plugin filename="gz-sim-sensors-system" name="gz::sim::systems::Sensors">
      <render_engine>ogre2</render_engine>
    </plugin>
    <plugin filename="gz-sim-imu-system" name="gz::sim::systems::Imu"/>
    <scene><shadows>0</shadows><ambient>0.6 0.6 0.6 1</ambient><background>0.85 0.88 0.92 1</background></scene>
    <physics name="3ms" type="ode"><max_step_size>0.003</max_step_size><real_time_factor>1</real_time_factor></physics>
    <light name="sun" type="directional">
      <cast_shadows>0</cast_shadows><pose>0 0 10 0 0 0</pose>
      <diffuse>0.85 0.85 0.85 1</diffuse><specular>0.3 0.3 0.3 1</specular>
      <direction>-0.4 0.2 -0.9</direction>
    </light>
    <model name="ground_plane"><static>1</static><link name="link">
      <collision name="collision"><geometry><plane><normal>0 0 1</normal><size>100 100</size></plane></geometry></collision>
      <visual name="visual"><geometry><plane><normal>0 0 1</normal><size>100 100</size></plane></geometry>
        <material><ambient>0.55 0.56 0.58 1</ambient><diffuse>0.55 0.56 0.58 1</diffuse></material></visual>
    </link></model>
"""


def box_model(name, x, y, sx, sy, h, rgb, collide=True, z0=0.0):
    color = " ".join(f"{c:.3f}" for c in rgb) + " 1"
    col = (f'<collision name="c"><geometry><box><size>{sx} {sy} {h}</size></box></geometry></collision>'
           if collide else "")
    return (f'    <model name="{name}"><static>1</static><pose>{x} {y} {z0 + h / 2} 0 0 0</pose>'
            f'<link name="link">{col}<visual name="v"><geometry><box><size>{sx} {sy} {h}</size></box>'
            f'</geometry><material><ambient>{color}</ambient><diffuse>{color}</diffuse></material></visual>'
            f"</link></model>\n")


def actor_model(a):
    """Kinematic (physics-free) model teleported along its path by qrsimbench.adapters.gazebo.actors.

    kind: worker (body cylinder + head sphere, hi-vis colours) or forklift (body + mast + forks).
    Visual-only on purpose: LiDAR (GPU ray casting) sees them, but teleported kinematic bodies would
    shove robots physically; contact is instead measured as human/vehicle separation.
    """
    x, y = a["path"][0]
    if a["kind"] == "worker":
        geo = ('<visual name="body"><pose>0 0 0.6 0 0 0</pose><geometry><cylinder><radius>0.2</radius>'
               '<length>1.2</length></cylinder></geometry><material><ambient>0.95 0.55 0.05 1</ambient>'
               '<diffuse>0.95 0.55 0.05 1</diffuse></material></visual>'
               '<visual name="head"><pose>0 0 1.38 0 0 0</pose><geometry><sphere><radius>0.14</radius>'
               '</sphere></geometry><material><ambient>0.9 0.75 0.6 1</ambient><diffuse>0.9 0.75 0.6 1'
               '</diffuse></material></visual>'
               '<visual name="helmet"><pose>0 0 1.5 0 0 0</pose><geometry><sphere><radius>0.15</radius>'
               '</sphere></geometry><material><ambient>1 0.9 0.1 1</ambient><diffuse>1 0.9 0.1 1</diffuse>'
               '</material></visual>'
               '')
    else:
        geo = ('<visual name="body"><pose>0 0 0.55 0 0 0</pose><geometry><box><size>1.6 0.9 1.0</size>'
               '</box></geometry><material><ambient>0.95 0.7 0.05 1</ambient><diffuse>0.95 0.7 0.05 1'
               '</diffuse></material></visual>'
               '<visual name="cab"><pose>-0.2 0 1.45 0 0 0</pose><geometry><box><size>0.9 0.85 0.8</size>'
               '</box></geometry><material><ambient>0.2 0.2 0.2 1</ambient><diffuse>0.2 0.2 0.2 1'
               '</diffuse></material></visual>'
               '<visual name="mast"><pose>0.85 0 1.1 0 0 0</pose><geometry><box><size>0.1 0.7 2.2</size>'
               '</box></geometry><material><ambient>0.3 0.3 0.3 1</ambient><diffuse>0.3 0.3 0.3 1'
               '</diffuse></material></visual>'
               '<visual name="forks"><pose>1.35 0 0.2 0 0 0</pose><geometry><box><size>1.0 0.6 0.06</size>'
               '</box></geometry><material><ambient>0.25 0.25 0.25 1</ambient><diffuse>0.25 0.25 0.25 1'
               '</diffuse></material></visual>'
               '')
    return (f'    <model name="{a["name"]}"><pose>{x} {y} 0 0 0 0</pose><link name="link">'
            f"<kinematic>true</kinematic><gravity>false</gravity>{geo}</link></model>\n")


def camera_sensor(name, pose, hfov, w=960, h=540, rate=15):
    """Demo camera publishing on gz topic qr_demo/<name> (recorded to video by qrsimbench)."""
    return (f'<sensor name="{name}" type="camera"><pose>{pose}</pose><always_on>1</always_on>'
            f"<update_rate>{rate}</update_rate><camera><horizontal_fov>{hfov}</horizontal_fov>"
            f"<image><width>{w}</width><height>{h}</height></image><clip><near>0.1</near><far>60</far></clip>"
            f'</camera><topic>qr_demo/{name}</topic></sensor>')


def camera_model(c):
    return (f'    <model name="cam_{c["name"]}"><static>1</static><link name="link">'
            f'{camera_sensor(c["name"], c["pose"], c.get("hfov", 1.2))}</link></model>\n')


def solids(layout):
    b, w = layout["bounds"], layout["wall"]
    t = w["thickness"]
    cx, cy = (b["x_min"] + b["x_max"]) / 2, (b["y_min"] + b["y_max"]) / 2
    lx, ly = b["x_max"] - b["x_min"] + 2 * t, b["y_max"] - b["y_min"] + 2 * t
    walls = [
        ("wall_n", cx, b["y_max"] + t / 2, lx, t),
        ("wall_s", cx, b["y_min"] - t / 2, lx, t),
        ("wall_e", b["x_max"] + t / 2, cy, t, ly),
        ("wall_w", b["x_min"] - t / 2, cy, t, ly),
    ]
    out = [(n, x, y, sx, sy, w["height"], w["color"]) for n, x, y, sx, sy in walls]
    for r in layout.get("racks", []):
        out.append((r["name"], r["x"], r["y"], r["sx"], r["sy"], r["h"], r.get("color", [0.2, 0.35, 0.6])))
        # Rack uprights protrude from the long faces at irregular spacing. Real racks have them, and
        # they give the 2D LiDAR longitudinal features so AMCL does not slide along featureless aisles.
        ups = r.get("uprights")
        if ups:
            d, sz = ups.get("protrude", 0.1), ups.get("size", 0.12)
            for i, f in enumerate(ups["at"]):
                ux = r["x"] - r["sx"] / 2 + f * r["sx"]
                for side in (-1, 1):
                    uy = r["y"] + side * (r["sy"] / 2 + d / 2)
                    out.append((f"{r['name']}_up{i}{'n' if side > 0 else 's'}", ux, uy, sz, d, r["h"],
                                [0.85, 0.45, 0.1]))
    for blk in layout.get("blocks", []):  # machines, conveyors, tables, columns ... (collidable)
        out.append((blk["name"], blk["x"], blk["y"], blk["sx"], blk["sy"], blk.get("h", 1.0),
                    blk.get("color", [0.5, 0.5, 0.5])))
    for i, c in enumerate(layout.get("clutter", [])):
        out.append((c.get("name", f"clutter_{i}"), c["x"], c["y"], c["sx"], c["sy"], c.get("h", 0.8),
                    c.get("color", [0.55, 0.4, 0.25])))
    return out


def build(layout_path: Path):
    layout = yaml.safe_load(layout_path.read_text())
    wid = layout["id"]
    world_dir, map_dir = ROOT / "simulation/worlds", ROOT / "simulation/maps"
    map_dir.mkdir(parents=True, exist_ok=True)

    sdf = [HEADER.format(src=layout_path.relative_to(ROOT))]
    for n, x, y, sx, sy, h, rgb in solids(layout):
        sdf.append(box_model(n, x, y, sx, sy, h, rgb))
    for n, s in layout["stations"].items():  # thin floor pads, no collision
        sdf.append(box_model(f"pad_{n}", s["x"], s["y"], 0.9, 0.9, 0.005, s["color"], collide=False))
    for i, mk in enumerate(layout.get("markings", [])):  # floor lane lines, visual only
        sdf.append(box_model(mk.get("name", f"mark_{i}"), mk["x"], mk["y"], mk["sx"], mk["sy"], 0.003,
                             mk.get("color", [0.95, 0.8, 0.1]), collide=False))
    for a in layout.get("actors", []):  # moving people / vehicles, driven by qrsimbench actors process
        sdf.append(actor_model(a))
    sdf.append("  </world>\n</sdf>\n")
    (world_dir / f"{wid}.sdf.xacro").write_text("".join(sdf))
    if layout.get("demo_cameras"):  # same world + fixed cameras that save frames (video recording)
        cams = "".join(camera_model(c) for c in layout["demo_cameras"])
        demo = "".join(sdf[:-1]) + cams + sdf[-1]
        (world_dir / f"{wid}_demo.sdf.xacro").write_text(demo)

    # Occupancy map: same solids rasterized (0 = occupied/black, 254 = free/white).
    res, b, t = layout["map_resolution"], layout["bounds"], layout["wall"]["thickness"]
    pad = t + 0.5
    ox, oy = b["x_min"] - pad, b["y_min"] - pad
    w = int(round((b["x_max"] - b["x_min"] + 2 * pad) / res))
    h = int(round((b["y_max"] - b["y_min"] + 2 * pad) / res))
    grid = np.full((h, w), 254, dtype=np.uint8)
    xs = ox + (np.arange(w) + 0.5) * res
    ys = oy + (np.arange(h) + 0.5) * res
    X, Y = np.meshgrid(xs, ys)
    for _n, x, y, sx, sy, _h, _rgb in solids(layout):
        grid[(np.abs(X - x) <= sx / 2) & (np.abs(Y - y) <= sy / 2)] = 0
    outside = (X < b["x_min"] - t) | (X > b["x_max"] + t) | (Y < b["y_min"] - t) | (Y > b["y_max"] + t)
    grid[outside] = 205  # unknown
    grid = np.flipud(grid)  # PGM row 0 is the top (max y)
    with open(map_dir / f"{wid}.pgm", "wb") as f:
        f.write(f"P5\n{w} {h}\n255\n".encode())
        f.write(grid.tobytes())
    (map_dir / f"{wid}.yaml").write_text(yaml.safe_dump({
        "image": f"{wid}.pgm", "mode": "trinary", "resolution": res, "origin": [ox, oy, 0.0],
        "negate": 0, "occupied_thresh": 0.65, "free_thresh": 0.25,
    }, sort_keys=False))
    print(f"wrote simulation/worlds/{wid}.sdf.xacro and simulation/maps/{wid}.{{pgm,yaml}} ({w}x{h})")


if __name__ == "__main__":
    build(Path(sys.argv[1]).resolve())
